import{_ as o,r as s,o as p,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"文件设置 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置文件结构","slug":"配置文件结构","link":"#配置文件结构","children":[]},{"level":2,"title":"访问配置值","slug":"访问配置值","link":"#访问配置值","children":[]},{"level":2,"title":"覆盖配置值","slug":"覆盖配置值","link":"#覆盖配置值","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/extend/settings/file-settings.md","filePath":"3.x/zh-cn/extend/settings/file-settings.md"}'),i={name:"3.x/zh-cn/extend/settings/file-settings.md"};function g(d,n,u,m,k,h){const e=s("pre-heading"),t=s("post-heading");return p(),c("div",null,[a(e),n[0]||(n[0]=l("h1",null,"文件设置",-1)),a(t),n[1]||(n[1]=r(`<p>文件设置将设置值存储在文件中，可以通过环境变量或应用程序文件覆盖。</p><h2 id="配置文件结构"><a href="#配置文件结构" class="header-anchor">#</a> 配置文件结构</h2><p>插件可以在插件目录的 <strong>config</strong> 子目录中使用基于文件的配置文件。以下是插件 <strong>config</strong> 目录的示例。</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── todo
|           └── <code>config</code>
|               ├── config.php  <em>← 配置文件</em>
|               └── custom.php  <em>← 配置文件</em></p>
</code></pre><p>配置文件是定义并返回<strong>数组</strong>的 PHP 脚本。以下是配置文件 <strong>config.php</strong> 的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;display&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">5</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="访问配置值"><a href="#访问配置值" class="header-anchor">#</a> 访问配置值</h2><p>使用 <code>Config</code> facade 访问配置文件中定义的配置值。<code>get</code> 方法接受以下格式的插件和配置名称（第一个参数）：<strong>acme.demo::maxItems</strong>。您还可以定义默认值（第二个参数），在配置参数不存在时返回。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>使用不同的配置文件名会影响键名。例如，名为 <strong>custom.php</strong> 的配置文件将在键名前添加 <code>custom</code> 前缀，使用以下格式：<strong>acme.demo::custom.maxItems</strong>。以下示例基于名为 <strong>custom.php</strong> 的配置文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::custom.maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="覆盖配置值"><a href="#覆盖配置值" class="header-anchor">#</a> 覆盖配置值</h2><p>插件配置文件可以通过应用程序创建匹配的本地配置文件来覆盖，例如，要覆盖 <strong>plugins/acme/demo/config/config.php</strong>，请创建名为 <strong>config/acme/todo/config.php</strong> 的文件。</p><pre class="dir-container"><code><p>├── config
|   └── <code>acme</code>
|       └── <code>todo</code>
|           └── config.php  <em>← 覆盖文件</em></p>
</code></pre><p>在覆盖的配置文件中，您只需返回要覆盖的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">20</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>如果您希望在不同环境中使用不同的配置（例如：<strong>dev</strong>、<strong>production</strong>），可以考虑使用 <code>env()</code> 辅助函数从环境变量中获取值。<code>env()</code> 函数接受环境变量名称（第一个参数）和变量不存在时的可选默认值（第二个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ACME_TODO_MAX_ITEMS&#39;</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>当环境变量 <code>ACME_TODO_MAX_ITEMS</code> 设置为其他值时，这将更改 <code>maxItems</code> 的值。例如，在应用程序的 <strong>.env</strong> 文件中。请参阅<a href="./../../setup/configuration.html">配置文章</a>了解如何根据环境更改这些值。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">ACME_TODO_MAX_ITEMS</span><span class="token punctuation">=</span><span class="token value attr-value">10</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../setup/configuration.html">通用配置</a></li></ul></div>`,22))])}const v=o(i,[["render",g]]);export{_ as __pageData,v as default};
